def maximumGap(nums):
    n = len(nums)
    if n < 2:
        return 0
    lo, hi = min(nums), max(nums)
    if lo == hi:
        return 0
    w = max(1, (hi - lo) // (n - 1))
    m = (hi - lo) // w + 1
    bmin = [None] * m
    bmax = [None] * m
    for x in nums:
        b = (x - lo) // w
        if bmin[b] is None or x < bmin[b]:
            bmin[b] = x
        if bmax[b] is None or x > bmax[b]:
            bmax[b] = x
    best = 0
    prev = lo
    for b in range(m):
        if bmin[b] is None:
            continue
        best = max(best, bmin[b] - prev)
        prev = bmax[b]
    return best
